$checks = 0;
$check = static function (bool $condition, string $message) use (&$checks): void { ++$checks; if (!$condition) { throw new RuntimeException($message); } };
$reject = static function (callable $work, string $code) use ($check): void { try { $work(); } catch (DomainError $e) { $check($e->errorCode === $code, 'Expected '.$code.' got '.$e->errorCode); return; } throw new RuntimeException('Expected '.$code); };
$db = new Database($GLOBALS['wpdb']);
Schema::install($db);
$entities = new EntityStore($db);
$r = new Records($db);
$tag = bin2hex(random_bytes(5));
$actor = wp_insert_user(['user_login' => 'marketplace-fixture-'.$tag, 'user_pass' => wp_generate_password(), 'user_email' => 'seller-'.$tag.'@example.invalid', 'role' => 'subscriber']);
$other = wp_insert_user(['user_login' => 'other-fixture-'.$tag, 'user_pass' => wp_generate_password(), 'user_email' => 'other-'.$tag.'@example.invalid', 'role' => 'subscriber']);
if (is_wp_error($actor) || is_wp_error($other)) { throw new RuntimeException('Synthetic user creation failed.'); }
$captureOrder = wc_create_order(['customer_id' => $actor]);
$captureOrderId = (string) $captureOrder->get_id();
$service = new SellerService($db, $entities);
