$check($seller['id'] === $again['id'], 'Application retry returns original organization');
$changed = $application; $changed['display_name'] = 'Other';
$reject(fn () => $service->apply($changed, $actor, 'apply-fixture-'.$tag.'-001', 999), 'idempotency_conflict');
$reject(fn () => $service->apply($application, $actor, 'apply-fixture-'.$tag.'-002', 0), 'current_terms_required');
$reject(fn () => $service->transition($seller['id'], ['target_state' => 'review', 'reason_code' => 'synthetic'], 1, $other, 'review-fixture-'.$tag.'-001'), 'verified_step_up_unavailable');
// Explicit test-only proof does not verify an identity provider or real payment provider.
$human = new class implements HumanVerifier { public function requireFresh(int $principal, string $purpose, string $digest): void {} };
$review = new SellerService($db, $entities, $human);
$reject(fn () => $review->transition($seller['id'], ['target_state' => 'review', 'reason_code' => 'synthetic'], 1, $actor, 'review-fixture-'.$tag.'-002'), 'independent_reviewer_required');
$reviewed = $review->transition($seller['id'], ['target_state' => 'review', 'reason_code' => 'synthetic'], 1, $other, 'review-fixture-'.$tag.'-003');
$check($reviewed['state'] === 'review' && $reviewed['version'] === 2, 'Independent scoped seller review is versioned');
$reject(fn () => $review->transition($seller['id'], ['target_state' => 'approved', 'reason_code' => 'synthetic'], 2, $other, 'review-fixture-'.$tag.'-004'), 'marketplace_activation_blocked');
// Direct test-only fixture setup, never an application approval path.
$db->wpdb()->update($db->table('sellers'), ['state' => 'approved'], ['id' => $seller['id']]);
$invitation = $review->invite($seller['id'], ['user_email' => 'other-'.$tag.'@example.invalid', 'capabilities' => ['commerce.offer.write']], $actor, 'invite-fixture-'.$tag.'-001');
$check($invitation['state'] === 'pending', 'Invitation is pending account acceptance');
$accepted = $review->acceptInvitation($invitation['resource_id'], $other);
$check($accepted['state'] === 'active' && $accepted['version'] === 2, 'Invitation is bound to the verified current account');
$reject(fn () => $review->acceptInvitation($invitation['resource_id'], $other), 'invitation_expired');
$ownerMembership = $db->wpdb()->get_row($db->wpdb()->prepare('SELECT * FROM '.$db->table('memberships').' WHERE seller_id=%s AND user_id=%d', $seller['id'], $actor), ARRAY_A);
$reject(fn () => $review->revoke($seller['id'], $ownerMembership['id'], 1, $actor, 'revoke-fixture-'.$tag.'-001'), 'last_owner');
$revoked = $review->revoke($seller['id'], $invitation['resource_id'], 2, $actor, 'revoke-fixture-'.$tag.'-002');
$check($revoked['state'] === 'revoked', 'Membership revocation changes live authority');
$inventory = new InventoryService($db);
$pool = $inventory->createPool($seller['id'], 'synthetic-origin', 1, 1);
$line = ['pool_id' => $pool['pool_id'], 'line_key' => 'item-001', 'quantity' => 1, 'authority_epoch' => 1];
$hold = $inventory->reserveGroup('hold-fixture-'.$tag.'-001', [$line], $actor);
$check($inventory->pool($pool['pool_id'])['reserved'] === 1, 'Database hold reserves physical quantity');
$check($inventory->reserveGroup('hold-fixture-'.$tag.'-001', [$line], $actor)[0]['id'] === $hold[0]['id'], 'Duplicate hold returns original result');
$reject(fn () => $inventory->reserveGroup('hold-fixture-'.$tag.'-002', [$line], $other), 'insufficient_stock');
