$verifiedInventory = new InventoryService($db, $proof);
$verifiedInventory->commit($hold[0]['id'], $captureOrderId, 'synthetic-capture'); $verifiedInventory->commit($hold[0]['id'], $captureOrderId, 'synthetic-capture');
$check($inventory->pool($pool['pool_id'])['on_hand'] === 0 && $inventory->pool($pool['pool_id'])['reserved'] === 0, 'Verified domain commit decrements once');
$reject(fn () => $inventory->release($hold[0]['id']), 'reservation_state_conflict');
$current = $inventory->pool($pool['pool_id']);
$adjusted = $inventory->adjust($pool['pool_id'], 2, 'received_supply', 1, $current['version'], $actor, 'adjust-fixture-'.$tag.'-001');
$check($adjusted['on_hand'] === 2, 'Physical supply adjustment recorded');
$check($inventory->adjust($pool['pool_id'], 2, 'received_supply', 1, $current['version'], $actor, 'adjust-fixture-'.$tag.'-001') === $adjusted, 'Identical adjustment retry ignores now-stale expected version');
$reject(fn () => $inventory->adjust($pool['pool_id'], 1, 'received_supply', 2, $adjusted['version'], $actor, 'adjust-fixture-'.$tag.'-002'), 'authority_epoch_conflict');
$reject(fn () => $inventory->adjust($pool['pool_id'], -3, 'damage', 1, $adjusted['version'], $actor, 'adjust-fixture-'.$tag.'-003'), 'stock_conflict');
$hold = $inventory->reserveGroup('hold-fixture-'.$tag.'-004', [$line], $actor);
$db->wpdb()->update($db->table('reservations'), ['expires_at' => '2020-01-01 00:00:00'], ['id' => $hold[0]['id']]);
$reject(fn () => $verifiedInventory->commit($hold[0]['id'], $captureOrderId, 'synthetic-capture'), 'reservation_expired');
