$activePool = $inventory->createPool($seller['id'], 'synthetic-other-origin', 1, 2);
$emptyPool = $inventory->createPool($seller['id'], 'synthetic-empty-origin', 1, 0);
$group = [['pool_id' => $activePool['pool_id'], 'line_key' => 'group-a', 'quantity' => 1, 'authority_epoch' => 1], ['pool_id' => $emptyPool['pool_id'], 'line_key' => 'group-b', 'quantity' => 1, 'authority_epoch' => 1]];
$reject(fn () => $inventory->reserveGroup('group-fixture-'.$tag.'-001', $group, $actor), 'insufficient_stock');
$check($inventory->pool($activePool['pool_id'])['reserved'] === 0, 'Failed required line rolls back the entire attempted checkout hold group');
