$reject(fn () => $inventory->adjust($activePool['pool_id'], 1, 'inspected_return', 1, $activeState['version'], $actor, 'restock-fixture-'.$tag.'-001', 'invented-inspection'), 'inspection_required');
$inspection = $entities->create('return', ['seller_id' => $seller['id'], 'restock_pool_id' => $activePool['pool_id'], 'state' => 'inspected', 'disposition' => 'resalable', 'inspected_quantity' => 1, 'restocked_quantity' => 0, 'inspection_evidence_ref' => 'synthetic-inspection-only'], $seller['id']);
$restocked = $inventory->adjust($activePool['pool_id'], 1, 'inspected_return', 1, $activeState['version'], $actor, 'restock-fixture-'.$tag.'-002', $inspection['id']);
$check($restocked['on_hand'] === 3, 'Independently inspected resalable return permits one physical restock');
$check($inventory->adjust($activePool['pool_id'], 1, 'inspected_return', 1, $activeState['version'], $actor, 'restock-fixture-'.$tag.'-002', $inspection['id']) === $restocked, 'Repeated inspected-restock command replays the original result');
$reject(fn () => $inventory->adjust($activePool['pool_id'], 1, 'inspected_return', 1, $restocked['version'], $actor, 'restock-fixture-'.$tag.'-003', $inspection['id']), 'inspection_required');
