$check(!$drift['matches'] && $drift['state'] === 'quarantined', 'Drift persists quarantine');
$reject(fn () => $inventory->reserveGroup('hold-fixture-'.$tag.'-005', [$line], $actor), 'stock_unavailable');

$entry = static fn (string $account, string $side, string $amount, string $seller = ''): array => ['account' => $account, 'side' => $side, 'seller_id' => $seller, 'amount' => ['amount_minor' => $amount, 'currency' => 'USD', 'exponent' => 2]];
$entries = [$entry('provider_clearing', 'D', '100'), $entry('seller_payable', 'C', '90', $seller['id']), $entry('platform_commission', 'C', '10')];
$ledger = new Ledger($db);
$journal = $ledger->post('journal-fixture-'.$tag.'-001', 'synthetic-order:1', $entries, $actor);
$check($ledger->post('journal-fixture-'.$tag.'-001', 'synthetic-order:1', $entries, $actor)['id'] === $journal['id'], 'Journal retry has one posting');
$count = (int) $db->wpdb()->get_var($db->wpdb()->prepare('SELECT COUNT(*) FROM '.$db->table('journal_entries').' WHERE journal_id=%s', $journal['id']));
$check($count === 3, 'Journal retry does not duplicate entries');
$reversed = array_map(static function (array $e): array { $e['side'] = $e['side'] === 'D' ? 'C' : 'D'; return $e; }, $entries);
$ledger->post('journal-fixture-'.$tag.'-002', 'synthetic-reversal:1', $reversed, $other, $journal['id']);
$reject(fn () => $ledger->post('journal-fixture-'.$tag.'-003', 'synthetic-reversal:2', $entries, $other, $journal['id']), 'invalid_reversal');
$statement = $ledger->sellerStatement($seller['id'], 'USD');
$check($statement['balances']['seller_payable']['amount_minor'] === '0' && $statement['available_payable'] === null, 'Statements preserve balances without inventing payout availability');
$reject(fn () => $ledger->post('journal-fixture-'.$tag.'-004', 'synthetic-reversal:3', $reversed, $other, $journal['id']), 'write_conflict');
$cursor = Cursor::issue($seller['id'], 'fixture:'.$actor);
$check(Cursor::read($cursor, 'fixture:'.$actor) === $seller['id'], 'Signed cursor preserves its bounded continuation');
$reject(fn () => Cursor::read($cursor, 'fixture:'.$other), 'cursor_scope_conflict');
$reject(fn () => Cursor::read(substr($cursor, 0, -1).(str_ends_with($cursor, '0') ? '1' : '0'), 'fixture:'.$actor), 'invalid_cursor');

$product = new WC_Product_Simple();
MarketplaceFixtureProducts::track($product, 'marketplace.integration', $tag);
$product->set_name('Synthetic marketplace fixture '.$tag); $product->set_status('publish'); $product->set_regular_price('10.00'); $product->set_manage_stock(true); $product->set_stock_quantity(5); $product->save();
$pool2 = $inventory->createPool($seller['id'], 'synthetic-origin', 1, 5);
$offers = new OfferService($db);
$terms = ['condition' => 'new', 'origin_id' => 'synthetic-origin', 'shipping_profile_ref' => 'synthetic-shipping', 'warranty_terms_ref' => 'synthetic-warranty', 'return_terms_ref' => 'synthetic-return', 'destination_regions' => ['US']];
$offer = $offers->createDraft($seller['id'], (string) $product->get_id(), null, $pool2['pool_id'], $terms, 'fixture-sku-'.$tag, new Money('1000', get_woocommerce_currency(), (int) wc_get_price_decimals()), 1);
$updated = $offers->update($offer['id'], ['seller_sku' => 'fixture-new-'.$tag], 1, $actor, 'offer-fixture-'.$tag.'-001');
$check($updated['version'] === 2, 'Own commercial update increments once');
$reject(fn () => $offers->update($offer['id'], ['seller_sku' => 'stale'], 1, $actor, 'offer-fixture-'.$tag.'-002'), 'version_conflict');
$reject(fn () => $offers->update($offer['id'], ['product_id' => '99'], 2, $actor, 'offer-fixture-'.$tag.'-003'), 'invalid_fields');
$order = wc_create_order(['customer_id' => $actor]); $order->add_product($product, 2);
$shippingItem = new WC_Order_Item_Shipping(); $shippingItem->set_method_title('Synthetic shipping'); $shippingItem->set_method_id('flat_rate'); $shippingItem->set_total('5.00'); $order->add_item($shippingItem);
$order->calculate_totals(); $order->save();
(new OrderSnapshots())->capture($order);
$items = $order->get_items(); $item = reset($items); $before = $item->get_meta('_wooshop_purchase_snapshot', true);
$product->set_name('Changed catalog name'); $product->set_regular_price('20.00'); $product->save();
(new OrderSnapshots())->capture(wc_get_order($order->get_id()));
$afterItems = wc_get_order($order->get_id())->get_items(); $afterItem = reset($afterItems);
$check($before === $afterItem->get_meta('_wooshop_purchase_snapshot', true), 'Native order snapshot survives catalog mutation');
$check($before['amounts']['net']['amount_minor'] === '2000', 'Snapshot uses original WooCommerce order value');

// A complete accepted marketplace snapshot/paid marker is a direct synthetic fixture, never provider proof.
$snapshot = $before; $snapshot['seller_id'] = $seller['id']; $snapshot['authority_mode'] = 'marketplace_plugin'; $snapshot['offer_id'] = $offer['id'];
$item->update_meta_data('_wooshop_purchase_snapshot', $snapshot); $item->update_meta_data('_wooshop_purchase_snapshot_digest', hash('sha256', Records::canonical($snapshot))); $item->update_meta_data('_wooshop_offer_id', $offer['id']); $item->save();
$zero = new Money('0', $order->get_currency(), (int) wc_get_price_decimals());
$allocationService = new AllocationService($db, $entities);
$plan = [['order_item_id' => (string) $item->get_id(), 'seller_id' => $seller['id'], 'origin_id' => 'synthetic-origin', 'fulfillment_type' => 'physical', 'amounts' => ['net' => $before['amounts']['net'], 'tax' => $before['amounts']['tax'], 'shipping' => Money::decimal('5.00', $order->get_currency(), (int) wc_get_price_decimals())->jsonSerialize(), 'shipping_tax' => $zero->jsonSerialize(), 'fees' => $zero->jsonSerialize(), 'fees_tax' => $zero->jsonSerialize()]]];
$wrongComponents = $plan; $wrongComponents[0]['amounts']['fees'] = $wrongComponents[0]['amounts']['shipping']; $wrongComponents[0]['amounts']['shipping'] = $zero->jsonSerialize();
$reject(fn () => $allocationService->create((string) $order->get_id(), $wrongComponents, 'allocation-fixture-'.$tag.'-000'), 'allocation_component_conflict');
$allocated = $allocationService->create((string) $order->get_id(), $plan, 'allocation-fixture-'.$tag.'-001');
$check(count($allocated) === 1 && $allocated[0]['lines'][0]['quantity'] === 2 && $allocated[0]['total']['amount_minor'] === '2500', 'Native order quantities and all totals allocate exactly once');
$check($allocationService->create((string) $order->get_id(), $plan, 'allocation-fixture-'.$tag.'-001')[0]['id'] === $allocated[0]['id'], 'Allocation retry returns existing group');
$badPlan = $plan; $badPlan[] = $plan[0];
$reject(fn () => $allocationService->create((string) $order->get_id(), $badPlan, 'allocation-fixture-'.$tag.'-002'), 'allocation_overlap');
$order->set_status('processing'); $order->set_date_paid(time()); $order->save();
$shipment = $allocationService->shipment(['allocation_id' => $allocated[0]['id'], 'line_quantities' => [['order_item_id' => (string) $item->get_id(), 'quantity' => 1]], 'carrier_code' => 'synthetic-no-carrier-call'], $actor, 'shipment-fixture-'.$tag.'-001');
$check($shipment['state'] === 'created' && $shipment['tracking_url'] === null, 'Preparing a shipment does not invent carrier delivery or tracking URL');
$reject(fn () => $allocationService->shipment(['allocation_id' => $allocated[0]['id'], 'line_quantities' => [['order_item_id' => (string) $item->get_id(), 'quantity' => 2]], 'carrier_code' => 'synthetic'], $actor, 'shipment-fixture-'.$tag.'-002'), 'shipment_quantity_conflict');
$returned = $allocationService->requestReturn(['order_id' => (string) $order->get_id(), 'order_item_id' => (string) $item->get_id(), 'quantity' => 1, 'reason_code' => 'synthetic-inspection-request'], $actor, 'return-fixture-'.$tag.'-001');
$check($returned['state'] === 'requested', 'Physical return request has separate state from money and stock');
$reject(fn () => $allocationService->requestReturn(['order_id' => (string) $order->get_id(), 'order_item_id' => (string) $item->get_id(), 'quantity' => 2, 'reason_code' => 'synthetic'], $actor, 'return-fixture-'.$tag.'-002'), 'return_quantity_conflict');

$module = new MarketplaceModule($db, $entities); $module->register();
$server = rest_get_server();
if (!isset($server->get_routes()['/commerce/v1/offers'])) { $module->routes(); }
wp_set_current_user($other);
$request = new WP_REST_Request('PATCH', '/commerce/v1/offers/'.$offer['id']); $request->set_header('Content-Type', 'application/json'); $request->set_header('If-Match', '"2"'); $request->set_header('Idempotency-Key', 'rest-offer-'.$tag.'-001'); $request->set_body('{"seller_sku":"foreign"}');
$response = rest_do_request($request);
$check($response->get_status() === 404, 'Foreign seller REST mutation is indistinguishable from missing');
$foreignStock = new WP_REST_Request('POST', '/commerce/v1/inventory-pools/'.$pool2['pool_id'].'/adjustments'); $foreignStock->set_header('Content-Type', 'application/json'); $foreignStock->set_header('If-Match', '"1"'); $foreignStock->set_header('Idempotency-Key', 'rest-stock-'.$tag.'-001'); $foreignStock->set_body('{"delta":1,"reason":"received_supply","authority_epoch":1}');
$check(rest_do_request($foreignStock)->get_status() === 404, 'Foreign seller stock adjustment is uniformly invisible');
wp_set_current_user($actor);
$ownAllocations = new WP_REST_Request('GET', '/commerce/v1/allocations'); $ownAllocations->set_query_params(['seller_id' => $seller['id']]);
$ownAllocationResponse = rest_do_request($ownAllocations);
$check($ownAllocationResponse->get_status() === 200 && count($ownAllocationResponse->get_data()['items']) === 1, 'Fulfillment membership implies own allocation reads and GET with an unset body succeeds');
$publicOffers = new WP_REST_Request('GET', '/commerce/v1/offers'); $publicOffers->set_query_params(['product_id' => (string) $product->get_id()]);
$publicOfferResponse = rest_do_request($publicOffers);
$check($publicOfferResponse->get_status() === 200 && $publicOfferResponse->get_data()['items'] === [], 'Bodyless public GET succeeds and does not expose a gated draft offer');
$request = new WP_REST_Request('PATCH', '/commerce/v1/offers/'.$offer['id']); $request->set_header('Content-Type', 'application/json'); $request->set_header('If-Match', '"2"'); $request->set_header('Idempotency-Key', 'rest-offer-'.$tag.'-002'); $request->set_body('{"seller_sku":"rest-own-'.$tag.'"}');
$response = rest_do_request($request);
$check($response->get_status() === 200 && $response->get_data()['version'] === 3, 'Authenticated own REST commercial mutation succeeds');
$request = new WP_REST_Request('PATCH', '/commerce/v1/offers/'.$offer['id']); $request->set_header('Content-Type', 'application/json'); $request->set_header('Idempotency-Key', 'rest-offer-'.$tag.'-003'); $request->set_body('{"seller_sku":"missing-version"}');
$check(rest_do_request($request)->get_status() === 428, 'Missing If-Match rejected');
$stock = new WP_REST_Request('POST', '/commerce/v1/inventory-pools/'.$pool2['pool_id'].'/adjustments'); $stock->set_header('Content-Type', 'application/json'); $stock->set_header('If-Match', '"1"'); $stock->set_header('Idempotency-Key', 'rest-stock-'.$tag.'-002'); $stock->set_body('{"delta":1,"reason":"received_supply","authority_epoch":1}');
$stockResponse = rest_do_request($stock);
$check($stockResponse->get_status() === 201 && $stockResponse->get_data()['on_hand'] === 6, 'Own stock REST adjustment records exactly one supplied unit');
$stockReplay = rest_do_request($stock);
$check($stockReplay->get_status() === 201 && $stockReplay->get_data() === $stockResponse->get_data(), 'Stock REST replay preserves its original version/result');
$stock->set_body('{"delta":2,"reason":"received_supply","authority_epoch":1}');
$check(rest_do_request($stock)->get_status() === 409, 'Stock REST key reuse with different body conflicts');
$product->update_meta_data('_wooshop_authority_mode', 'marketplace_plugin'); $product->set_stock_quantity(0); $product->set_backorders('no'); $product->set_stock_status('outofstock'); $product->save();
$guard = new NativeGuard();
