$cleanedProduct = wc_get_product($product->get_id());
$check($cleanedProduct->get_status() === 'draft' && $cleanedProduct->get_meta('_wooshop_test_origin', true) === 'marketplace.integration' && $cleanedProduct->get_meta('_wooshop_test_run', true) === $tag, 'Only this run\'s proven test product is drafted and annotated after verification');
echo 'PASS '.$checks." isolated WP/WooCommerce/MariaDB assertions; synthetic proof is not identity/payment-provider verification.\n";
echo 'CONCURRENCY_POOL='.$pool2['pool_id']."\n";
